	private static final String PREFIX = "PREFIX ex: <urn:shipment:> ";
	private static final String SERVICE = "http://replay.invalid/sparql";
	private static final int STOPS = 96;
	private static final BindingSet EMPTY = EmptyBindingSet.getInstance();
	private static final ThreadMXBean MEMORY = ManagementFactory.getPlatformMXBean(ThreadMXBean.class);

