	private static QueryEvaluationStep prepare(LmdbStore store, SailDataset dataset, String query) {
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, PREFIX + query, null);
		var stats = store.getSailStore().getEvaluationStatistics();
		var source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
		var strategy = store.getEvaluationStrategyFactory()
				.createEvaluationStrategy(parsed.getDataset(), source, stats);
		var root = parsed.getTupleExpr() instanceof QueryRoot existing ? existing
				: new QueryRoot(parsed.getTupleExpr());
		return strategy.precompile(strategy.optimize(root, stats, EMPTY));
	}

	private static void measure(String label, Workload work, int index, String mode,
			Supplier<CloseableIteration<BindingSet>> evaluation, long start, long before, Replay replay) {
		long first;
		int count = 0;
		int responses = replay.responses;
		try (var rows = evaluation.get()) {
			if (rows.hasNext()) {
				rows.next();
				count++;
			}
			first = System.nanoTime();
			while (rows.hasNext()) {
				rows.next();
				count++;
			}
		}
		long end = System.nanoTime();
		long bytes = MEMORY.getTotalThreadAllocatedBytes() - before;
		requireResponses(work, replay.responses - responses);
		if (count != work.expected.size()) {
			throw new AssertionError(work.name + " returned " + count + " rows");
		}
		if (index >= 0) {
			print(label, work.name, index, mode, first - start, end - start, bytes, count);
		}
	}

	private static void requireResponses(Workload work, int count) {
		int expected = work.remoteStride >= 0 ? 1 : 0;
		if (count != expected) {
			throw new AssertionError(work.name + " decoded " + count + " response documents, expected " + expected);
		}
	}

	private static void print(String label, String name, int index, String mode, long first, long drain, long bytes,
			int count) {
		System.out.printf("SAMPLE,%s,%s,%d,%s,%d,%d,%d,%d%n", label, name, index, mode, first, drain, bytes, count);
	}

	private static void verify(Workload work, CloseableIteration<BindingSet> rows) {
		var anchors = new MapBindingSet();
		for (int i = 1; i < STOPS; i += 2) {
			anchors.addBinding("localStop" + i, stop(i));
		}
		var actual = new ArrayList<BindingSet>();
		rows.forEachRemaining(actual::add);
		if (!sameBag(work.expected, actual, anchors)) {
			throw new AssertionError("Result identity or multiplicity differed for " + work.name);
		}
	}

	static boolean sameBag(List<BindingSet> expected, List<BindingSet> actual, BindingSet anchors) {
		// Binding names in this witness are disjoint from workload columns. Matching it first fixes input identity.
		var expectedWithAnchors = new ArrayList<>(expected);
		expectedWithAnchors.addFirst(anchors);
		var actualWithAnchors = new ArrayList<>(actual);
		actualWithAnchors.addFirst(anchors);
		return QueryResults.equals(new IteratingTupleQueryResult(List.of(), expectedWithAnchors),
				new IteratingTupleQueryResult(List.of(), actualWithAnchors));
	}

	private static List<Workload> workloads() {
		List<BindingSet> scan = new ArrayList<>();
		List<BindingSet> join = new ArrayList<>();
		List<BindingSet> path = new ArrayList<>();
		List<BindingSet> groups = new ArrayList<>();
		for (int i = 0; i < STOPS; i++) {
			scan.add(row("stop", stop(i), "depot", iri("depot" + i % 3)));
			if (i > 0) {
				join.add(row("stop", stop(i - 1), "depot", iri("depot" + i % 3)));
				path.add(row("stop", stop(i), null, null));
			}
		}
		for (int i = 0; i < 3; i++) {
			groups.add(row("depot", iri("depot" + i), "n", VF.createLiteral(BigInteger.valueOf(STOPS / 3))));
		}
		List<Workload> result = new ArrayList<>();
		result.add(new Workload("scan", "SELECT ?stop ?depot WHERE { ?stop ex:depot ?depot }", scan, -1));
		result.add(
				new Workload("join", "SELECT ?stop ?depot WHERE { ?stop ex:next ?s . ?s ex:depot ?depot }", join, -1));
		result.add(new Workload("group",
				"SELECT ?depot (COUNT(?stop) AS ?n) WHERE { ?stop ex:depot ?depot } GROUP BY ?depot", groups, -1));
		result.add(new Workload("path-short", "SELECT ?stop WHERE { ex:stop0 ex:next/ex:next ?stop }",
				List.of(path.get(1)), -1));
		result.add(new Workload("path-long", "SELECT ?stop WHERE { ex:stop0 ex:next+ ?stop }", path, -1));
		for (int stride : List.of(0, 12, 1)) {
			List<BindingSet> remote = new ArrayList<>();
			for (int i = 0; i < STOPS; i++) {
				int id = i / 2;
				Value value = stride > 0 && id % stride == 0 ? VF.createBNode("remote" + id) : iri("remote" + id);
				remote.add(row("stop", value, "depot", iri("depot" + i % 3)));
			}
			String query = "SELECT ?stop ?depot WHERE { SERVICE <" + SERVICE + "> { ?stop ex:depot ?depot } }";
			String density = stride == 0 ? "zero" : stride == 1 ? "dense" : "sparse";
			result.add(new Workload("service-" + density, query, remote, stride));
		}
		return result;
	}

	private static MapBindingSet row(String first, Value value, String second, Value other) {
		var row = new MapBindingSet();
		row.addBinding(first, value);
		if (second != null) {
			row.addBinding(second, other);
		}
		return row;
	}

	private static Resource stop(int index) {
		return index % 2 == 0 ? iri("stop" + index) : VF.createBNode("stop" + index);
	}

	private static IRI iri(String local) {
		return VF.createIRI("urn:shipment:", local);
	}

	private static byte[] document(int stride) {
		var rows = new StringJoiner(",");
		for (int i = 0; i < STOPS; i++) {
			int id = i / 2;
			boolean blank = stride > 0 && id % stride == 0;
			String value = blank ? "wire" + id : iri("remote" + id).stringValue();
			rows.add("{\"stop\":{\"type\":\"" + (blank ? "bnode" : "uri") + "\",\"value\":\"" + value
					+ "\"},\"depot\":{\"type\":\"uri\",\"value\":\"" + iri("depot" + i % 3) + "\"}}");
		}
		return ("{\"head\":{\"vars\":[\"stop\",\"depot\"]},\"results\":{\"bindings\":[" + rows + "]}}")
				.getBytes(StandardCharsets.UTF_8);
	}

